import os
import time
import ctypes

import numpy as np
from scipy.linalg import blas, lapack

try:
    from threadpoolctl import threadpool_info as _tpi
except Exception:  # pragma: no cover
    _tpi = None


def _p_dsygvd(A, B):
    return lapack.dsygvd(A, B, 1, b'N', b'L')[0]


def _p_inv(A, B):
    L = np.linalg.cholesky(B)
    Li = np.linalg.inv(L)
    At = Li @ A @ Li.T
    return np.linalg.eigvalsh(At)


def _p_trmm(A, B):
    L = np.linalg.cholesky(B)
    Li, _ = lapack.dtrtri(L, lower=1, overwrite_c=1)
    M = blas.dtrmm(1.0, Li, A, side=1, lower=1, trans_a=1)
    C = blas.dtrmm(1.0, Li, M, side=0, lower=1, trans_a=0, overwrite_b=1)
    return np.linalg.eigvalsh(C)


def _ref(A, B):
    L = np.linalg.cholesky(B)
    Linv = np.linalg.inv(L)
    Atilde = Linv @ A @ Linv.T
    return sorted(np.linalg.eigh(Atilde)[0], reverse=True)


_PIPES = [("dsygvd", _p_dsygvd), ("inv", _p_inv), ("trmm", _p_trmm)]


class Solver:
    def __init__(self, **kwargs):
        self._setters = []
        self._orig = []
        try:
            if _tpi is not None:
                for d in _tpi():
                    if d.get("user_api") != "blas":
                        continue
                    lib = ctypes.CDLL(d["filepath"])
                    for name in ("scipy_openblas_set_num_threads64_",
                                 "openblas_set_num_threads64_",
                                 "scipy_openblas_set_num_threads",
                                 "openblas_set_num_threads"):
                        f = getattr(lib, name, None)
                        if f is not None:
                            f.argtypes = [ctypes.c_int]
                            f.restype = None
                            self._setters.append(f)
                            self._orig.append(d["num_threads"])
                            break
        except Exception:
            self._setters = []
        self._cfg = (_p_inv, None)
        try:
            self._tune()
        except Exception:
            self._cfg = (_p_inv, None)

    def _set(self, t):
        for f in self._setters:
            f(int(t))

    def _restore(self):
        for f, t in zip(self._setters, self._orig):
            f(int(t))

    def _tune(self):
        if not self._setters:
            return
        n = 768
        rng = np.random.default_rng(12345)
        X = rng.standard_normal((n, n))
        A = X + X.T
        Y = rng.standard_normal((n, n))
        B = Y @ Y.T / n + np.eye(n)
        ncpu = len(os.sched_getaffinity(0))
        cands = sorted({2, 4, 8, ncpu} & set(range(1, ncpu + 1)))
        best = None
        for name, fn in _PIPES:
            for t in cands:
                tm = 1e9
                for _ in range(3):
                    _ref(A, B)
                    self._set(t)
                    t0 = time.perf_counter()
                    try:
                        fn(A, B)
                    finally:
                        self._restore()
                    tm = min(tm, time.perf_counter() - t0)
                if best is None or tm < best[0]:
                    best = (tm, fn, t)
        self._cfg = (best[1], best[2])

    def solve(self, problem, **kwargs):
        A, B = problem
        if A.shape[0] <= 256:
            w, _, info = lapack.dsygvd(A, B, 1, b'N', b'L')
            if info == 0:
                return w[::-1].tolist()
        fn, t = self._cfg
        if t is None or not self._setters:
            w = fn(A, B)
        else:
            self._set(t)
            try:
                w = fn(A, B)
            finally:
                self._restore()
        return w[::-1].tolist()
